//! The Rust of Relay.IStore, ported from C# (CodeCoreMorph, D-84).
use codecoremorph_runtime::tasks::{CancellationToken, Task};

/// Where a cache reads what it doesn't have yet. A C# implementation reaches the Rust through
/// the bridge; its value may be None, as a C# string may be null.
pub trait Store: Send + Sync {
    fn fetch_async(&self, key: &str, cancellation: &CancellationToken) -> Task<Option<String>>;
}

//! The bridge of Relay.Cache: the exports its C# façade calls (CodeCoreMorph, D-84).
use std::ffi::{c_char, c_void, CString};
use std::sync::Arc;

use codecoremorph_runtime::tasks::{CancellationToken, Task};
use codecoremorph_runtime::Exception;

use super::ccm::{self, ccm_release_fn, ccm_status, Handle, ManagedRef};
use super::ccm_tasks::{self, TokenOut};
use crate::cache::Cache;
use crate::i_store::Store;

/// IStore implemented in C#: `fetch(context, key, cancellation, source)` starts the C# store's
/// FetchAsync and has its task complete `source`, a native task's (`ccm_source_done_string`,
/// D-96); it returns CCM_MANAGED when FetchAsync throws at once.
pub type relay_fetch_fn = Option<
    unsafe extern "C" fn(
        context: *mut c_void,
        key: *const c_char,
        cancellation: *mut c_void,
        source: *mut c_void,
    ) -> ccm_status,
>;

pub struct relay_Cache(());

impl Handle for relay_Cache {
    type Target = Cache;
}

type Fetch = unsafe extern "C" fn(*mut c_void, *const c_char, *mut c_void, *mut c_void) -> ccm_status;

/// A C# IStore: its fetch is a C# task the Rust awaits (D-96).
struct ManagedStore {
    managed: Arc<ManagedRef>,
    fetch: Fetch,
}

impl Store for ManagedStore {
    fn fetch_async(&self, key: &str, cancellation: &CancellationToken) -> Task<Option<String>> {
        let token = TokenOut::new(cancellation);
        let key = CString::new(key.replace('\0', " ")).unwrap_or_default();
        ccm_tasks::managed_task(|source| {
            // SAFETY: the C# store's callback, with the context it gave; the key and the token
            // live through the call.
            unsafe { (self.fetch)(self.managed.context(), key.as_ptr(), token.get(), source) }
        })
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_release(handle: *mut relay_Cache) {
    ccm::release(handle);
}

#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_key(handle: *const relay_Cache) -> u64 {
    ccm::key(handle)
}

/// `Cache(IStore)`: the C# store as its context (a GCHandle, null for null), fetch and release.
#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_new(
    store: *mut c_void,
    fetch: relay_fetch_fn,
    release: ccm_release_fn,
    result: *mut *mut relay_Cache,
) -> ccm_status {
    let managed = ManagedRef::new(store, release); // owned from here, however the rest fails
    ccm::guard(|| {
        let proxy: Option<Arc<dyn Store>> = if store.is_null() {
            None
        } else {
            Some(Arc::new(ManagedStore { managed, fetch: ccm::callback(fetch)? }))
        };
        ccm::put(result, ccm::to_handle::<relay_Cache>(Cache::new(proxy)?));
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_count(handle: *const relay_Cache, result: *mut i32) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::from_handle(handle)?.count());
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_fetches(handle: *const relay_Cache, result: *mut i32) -> ccm_status {
    ccm::guard(|| {
        ccm::put(result, ccm::from_handle(handle)?.fetches());
        Ok(())
    })
}

/// GetAsync: completes `task`, the façade's C# task, with a string (D-96).
#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_get_async(
    handle: *const relay_Cache,
    key: *const c_char,
    cancellation: *mut c_void,
    task: *mut c_void,
) -> ccm_status {
    ccm::guard(|| {
        let cache = Arc::clone(ccm::from_handle(handle)?);
        let token = ccm_tasks::token(cancellation);
        // The null check is the task's, as the async C#'s was.
        ccm_tasks::start(task, || Ok(cache.get_async(ccm::str_in(key, "key")?, token)));
        Ok(())
    })
}

/// GetManyAsync: completes `task` with a string array.
#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_get_many_async(
    handle: *const relay_Cache,
    keys_data: *const *const c_char,
    keys_count: i32,
    cancellation: *mut c_void,
    task: *mut c_void,
) -> ccm_status {
    ccm::guard(|| {
        let cache = Arc::clone(ccm::from_handle(handle)?);
        let token = ccm_tasks::token(cancellation);
        ccm_tasks::start(task, || {
            let keys = ccm::strings(keys_data, keys_count, "keys")?
                .into_iter()
                .map(|key| key.ok_or_else(|| Exception::argument_null("key")))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(cache.get_many_async(keys, token))
        });
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn relay_Cache_clear(handle: *const relay_Cache) -> ccm_status {
    ccm::guard(|| {
        ccm::from_handle(handle)?.clear();
        Ok(())
    })
}

//! The Rust of Relay.Cache, ported from C# (CodeCoreMorph, D-84). Its async members spawn their
//! bodies on the runtime's tasks; Task.WhenAll is `tasks::when_all`.
use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

use codecoremorph_runtime::tasks::{self, CancellationToken, Task};
use codecoremorph_runtime::{Exception, Result};

use crate::i_store::Store;

#[derive(Default)]
struct State {
    entries: HashMap<String, String>,
    fetches: i32,
}

/// Values by key, fetched from a store once and kept. Shared: an async member holds the cache
/// until its task is done, as the C# object lives while its async method runs; no lock is
/// held across an `.await`.
pub struct Cache {
    store: Arc<dyn Store>,
    state: Mutex<State>,
}

impl Cache {
    pub fn new(store: Option<Arc<dyn Store>>) -> Result<Arc<Cache>> {
        let store = store.ok_or_else(|| Exception::argument_null("store"))?;
        Ok(Arc::new(Cache { store, state: Mutex::default() }))
    }

    fn state(&self) -> MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn count(&self) -> i32 {
        i32::try_from(self.state().entries.len()).unwrap_or(i32::MAX)
    }

    /// How many values the store has given.
    pub fn fetches(&self) -> i32 {
        self.state().fetches
    }

    pub fn get_async(self: &Arc<Self>, key: String, cancellation: CancellationToken) -> Task<String> {
        let this = Arc::clone(self);
        tasks::spawn(async move {
            let hit = this.state().entries.get(&key).cloned();
            if let Some(hit) = hit {
                return Ok(hit);
            }
            let value = this.store.fetch_async(&key, &cancellation).await?;
            let value = value.ok_or_else(|| {
                Exception::invalid_operation(format!("The store has no value for '{key}'."))
            })?;
            let mut state = this.state();
            state.entries.insert(key, value.clone());
            state.fetches += 1;
            Ok(value)
        })
    }

    /// Each key's value, fetched at once, in the keys' order.
    pub fn get_many_async(
        self: &Arc<Self>,
        keys: Vec<String>,
        cancellation: CancellationToken,
    ) -> Task<Vec<String>> {
        let pending = keys.into_iter().map(|key| self.get_async(key, cancellation.clone())).collect();
        tasks::when_all(pending)
    }

    pub fn clear(&self) {
        self.state().entries.clear();
    }
}

