//! The Rust of Relay.TransientException, ported from C# (CodeCoreMorph, D-84).
use codecoremorph_runtime::Exception;

/// The .NET type of TransientException: a failure a later attempt may not have.
pub const TRANSIENT: &str = "Relay.TransientException";

/// `new TransientException(message)`.
pub fn transient(message: impl Into<String>) -> Exception {
    Exception::new(TRANSIENT, message)
}

