//! The bridge of Relay.Retry: the exports its C# façade calls (CodeCoreMorph, D-84).
use std::ffi::c_void;
use std::sync::Arc;

use codecoremorph_runtime::tasks::CancellationToken;

use super::ccm::{self, ccm_release_fn, ccm_status, ManagedRef};
use super::ccm_tasks::{self, TokenOut};
use crate::retry::{self, Action};

/// Func<CancellationToken, Task<string>> from C#: `act(context, cancellation, source)` calls it
/// and has its task complete `source` (`ccm_source_done_string`, D-96); CCM_MANAGED when it
/// throws at once.
pub type relay_action_fn = Option<
    unsafe extern "C" fn(context: *mut c_void, cancellation: *mut c_void, source: *mut c_void) -> ccm_status,
>;

/// RunAsync: the action as its context (null for null), act and release; the pause in
/// TimeSpan's ticks; completes `task` with a string.
#[unsafe(no_mangle)]
pub extern "C" fn relay_Retry_run_async(
    action: *mut c_void,
    act: relay_action_fn,
    release: ccm_release_fn,
    attempts: i32,
    pause_ticks: i64,
    cancellation: *mut c_void,
    task: *mut c_void,
) -> ccm_status {
    let managed = ManagedRef::new(action, release); // owned from here
    ccm::guard(|| {
        let call: Option<Action> = if action.is_null() {
            None
        } else {
            let act = ccm::callback(act)?;
            Some(Arc::new(move |token: CancellationToken| {
                let out = TokenOut::new(&token);
                ccm_tasks::managed_task(|source| {
                    // SAFETY: the C# action's callback, with the context it gave; the token
                    // lives through the call.
                    unsafe { act(managed.context(), out.get(), source) }
                })
            }))
        };
        let token = ccm_tasks::token(cancellation);
        let pause = ccm_tasks::milliseconds(pause_ticks).unwrap_or_default();
        ccm_tasks::start(task, || Ok(retry::run_async(call, attempts, pause, token)));
        Ok(())
    })
}

//! The Rust of Relay.Retry, ported from C# (CodeCoreMorph, D-84).
use std::sync::Arc;
use std::time::Duration;

use codecoremorph_runtime::tasks::{self, CancellationToken, Task};
use codecoremorph_runtime::Exception;

use crate::transient_exception::TRANSIENT;

/// Func<CancellationToken, Task<string>>: its value may be None, as a C# string may be null.
pub type Action = Arc<dyn Fn(CancellationToken) -> Task<Option<String>> + Send + Sync>;

/// Runs an action again after a transient failure (`catch (TransientException) when (attempt <
/// attempts)`: a TransientException, or one derived from it, while attempts are left).
pub fn run_async(
    action: Option<Action>,
    attempts: i32,
    pause: Duration,
    cancellation: CancellationToken,
) -> Task<Option<String>> {
    tasks::spawn(async move {
        let action = action.ok_or_else(|| Exception::argument_null("action"))?;
        if attempts < 1 {
            return Err(Exception::argument_out_of_range(
                "attempts",
                "At least one attempt is needed.",
            ));
        }
        let mut attempt = 1;
        loop {
            match action(cancellation.clone()).await {
                Ok(value) => return Ok(value),
                Err(e) if e.is_a(TRANSIENT) && attempt < attempts => {
                    tasks::delay(Some(pause), &cancellation).await?;
                }
                Err(e) => return Err(e),
            }
            attempt += 1;
        }
    })
}

