//! tests/Relay.Tests/CacheTests.cs and its Stores.cs, translated to Rust (CodeCoreMorph, D-84).
//! A test waits for a task with `wait()`; C#'s Task.Yield is a zero delay.
use std::collections::HashMap;
use std::sync::atomic::{AtomicI32, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use codecoremorph_runtime::tasks::{self, CancellationToken, CancellationTokenSource, Task, TaskCompletionSource};
use codecoremorph_runtime::Exception;
use relay_rs::cache::Cache;
use relay_rs::i_store::Store;

/// A store of fixed values that answers after a yield; a key it lacks fails the fetch.
struct DictionaryStore {
    values: HashMap<String, Option<String>>,
    calls: AtomicI32,
}

impl Store for DictionaryStore {
    fn fetch_async(&self, key: &str, _cancellation: &CancellationToken) -> Task<Option<String>> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        let found = self.values.get(key).cloned();
        let key = key.to_string();
        tasks::spawn(async move {
            tasks::delay(Some(Duration::ZERO), &CancellationToken::none()).await?;
            found.ok_or_else(|| Exception::key_not_found(format!("The store has nothing under '{key}'.")))
        })
    }
}

/// A store whose fetches wait until the test lets each one go.
#[derive(Default)]
struct GatedStore {
    pending: Mutex<HashMap<String, Arc<TaskCompletionSource<Option<String>>>>>,
}

impl Store for GatedStore {
    fn fetch_async(&self, key: &str, _cancellation: &CancellationToken) -> Task<Option<String>> {
        let gate = Arc::new(TaskCompletionSource::new());
        self.pending.lock().unwrap().insert(key.to_string(), Arc::clone(&gate));
        gate.task()
    }
}

impl GatedStore {
    fn wait_for(&self, count: usize) {
        let deadline = Instant::now() + Duration::from_secs(10);
        while self.pending.lock().unwrap().len() < count {
            assert!(Instant::now() < deadline, "the fetches didn't come");
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    fn release(&self, key: &str, value: &str) {
        let gate = Arc::clone(&self.pending.lock().unwrap()[key]);
        gate.set_result(Some(value.to_string()));
    }
}

/// A store that never answers: only cancellation ends a fetch.
#[derive(Default)]
struct SilentStore {
    seen: Mutex<Option<CancellationToken>>,
}

impl Store for SilentStore {
    fn fetch_async(&self, _key: &str, cancellation: &CancellationToken) -> Task<Option<String>> {
        *self.seen.lock().unwrap() = Some(cancellation.clone());
        let cancellation = cancellation.clone();
        tasks::spawn(async move {
            tasks::delay(None, &cancellation).await?;
            Ok(Some("never".to_string()))
        })
    }
}

fn store() -> Arc<DictionaryStore> {
    let values = [("a", "alpha"), ("b", "beta"), ("c", "gamma")]
        .into_iter()
        .map(|(k, v)| (k.to_string(), Some(v.to_string())))
        .collect();
    Arc::new(DictionaryStore { values, calls: AtomicI32::new(0) })
}

fn none() -> CancellationToken {
    CancellationToken::none()
}

#[test]
fn a_value_is_fetched_once_then_kept() {
    let values = store();
    let cache = Cache::new(Some(values.clone())).unwrap();
    assert_eq!("alpha", cache.get_async("a".into(), none()).wait().unwrap());
    assert_eq!("alpha", cache.get_async("a".into(), none()).wait().unwrap());
    assert_eq!(1, values.calls.load(Ordering::SeqCst));
    assert_eq!(1, cache.fetches());
    assert_eq!(1, cache.count());
}

#[test]
fn many_keys_are_fetched_at_once_in_their_order() {
    let gated = Arc::new(GatedStore::default());
    let cache = Cache::new(Some(gated.clone())).unwrap();
    let many = cache.get_many_async(vec!["x".into(), "y".into(), "z".into()], none());
    gated.wait_for(3);
    assert!(!many.is_completed());
    gated.release("z", "zed");
    gated.release("y", "why");
    gated.release("x", "ex");
    assert_eq!(vec!["ex", "why", "zed"], many.wait().unwrap());
    assert_eq!(3, cache.count());
}

#[test]
fn a_failed_fetch_faults_the_task_with_the_stores_exception() {
    let cache = Cache::new(Some(store())).unwrap();
    let e = cache.get_async("nope".into(), none()).wait().unwrap_err();
    assert!(e.is("System.Collections.Generic.KeyNotFoundException"));
    assert_eq!("The store has nothing under 'nope'.", e.message());
    assert_eq!(0, cache.count());
}

#[test]
fn a_null_value_is_refused() {
    let values = [("n".to_string(), None)].into_iter().collect();
    let cache = Cache::new(Some(Arc::new(DictionaryStore { values, calls: AtomicI32::new(0) }))).unwrap();
    let e = cache.get_async("n".into(), none()).wait().unwrap_err();
    assert!(e.is("System.InvalidOperationException"));
    assert_eq!("The store has no value for 'n'.", e.message());
}

#[test]
fn one_failure_faults_the_whole_batch() {
    let cache = Cache::new(Some(store())).unwrap();
    let keys = vec!["a".into(), "nope".into(), "b".into()];
    let e = cache.get_many_async(keys, none()).wait().unwrap_err();
    assert!(e.is("System.Collections.Generic.KeyNotFoundException"));
}

#[test]
fn canceling_a_fetch_cancels_the_task() {
    let silent = Arc::new(SilentStore::default());
    let cache = Cache::new(Some(silent.clone())).unwrap();
    let source = CancellationTokenSource::new();
    let fetch = cache.get_async("a".into(), source.token());
    assert!(!fetch.is_completed());
    source.cancel();
    assert!(fetch.wait().unwrap_err().is("System.Threading.Tasks.TaskCanceledException"));
    assert!(fetch.is_canceled());
    let seen = silent.seen.lock().unwrap().clone().unwrap();
    assert!(seen.can_be_canceled());
